from __future__ import annotations
from dataclasses import dataclass
from cbim_sdk import CBIMProject
from cbim_sdk.models import Equipment,Fitting,Pipe,Point3D,SourceRef,System
from ..cad.model import CadDocument,CadInsert,CadLine,CadPolyline
from .common import diameter_m_with_source,fitting_type_from_label
from .semantics import classify_mep_entity

@dataclass(frozen=True)
class FireConfig: default_diameter_mm: float=50.0

class FireRecognizer:
    def __init__(self,config:FireConfig=FireConfig()): self.config=config
    def recognize(self,document:CadDocument,project:CBIMProject)->CBIMProject:
        p=project.model_copy(deep=True); system=None
        def ensure():
            nonlocal system
            if system is None:
                system=System(name='Combate a incêndio',discipline='fire',classification='fire_protection'); p.systems.append(system)
            return system.id
        for entity in document.entities:
            semantic=classify_mep_entity(entity)
            if not semantic or semantic.discipline!='fire': continue
            sid=ensure(); src=[SourceRef(source_id=document.source_id,entity_id=entity.id,layer=entity.layer,metadata={'semantic_evidence':semantic.evidence})]
            diameter,diameter_source=diameter_m_with_source(entity,self.config.default_diameter_mm)
            common={'service':'fire','semantic_evidence':semantic.evidence,'diameter_source':diameter_source}
            if diameter_source=='recognizer_default': common.update({'requires_review':True,'review_reason':'diameter_default'})
            if semantic.target=='pipe' and isinstance(entity,CadLine):
                p.elements.append(Pipe(path=[Point3D(x=entity.start.x,y=entity.start.y,z=entity.start.z),Point3D(x=entity.end.x,y=entity.end.y,z=entity.end.z)],diameter=diameter,system_id=sid,confidence=.96,source_refs=src,properties=common))
            elif semantic.target=='pipe' and isinstance(entity,CadPolyline):
                p.elements.append(Pipe(path=[Point3D(x=q.x,y=q.y,z=q.z) for q in entity.points],diameter=diameter,system_id=sid,confidence=.95,source_refs=src,properties=common))
            elif semantic.target=='fitting' and isinstance(entity,CadInsert):
                pos=Point3D(x=entity.position.x,y=entity.position.y,z=entity.position.z); ft,angle=fitting_type_from_label(f'{entity.layer} {entity.block_name}'); props=dict(common)
                if angle is not None: props['angle_deg']=angle
                if ft=='other': props.update({'requires_review':True,'review_reason':'fitting_type_unknown'})
                p.elements.append(Fitting(position=pos,fitting_type=ft,nominal_diameter=diameter,system_id=sid,confidence=.97 if ft!='other' else .88,source_refs=src,properties=props))
            elif semantic.target=='equipment' and isinstance(entity,CadInsert):
                pos=Point3D(x=entity.position.x,y=entity.position.y,z=entity.position.z)
                p.elements.append(Equipment(position=pos,equipment_type=entity.block_name,system_id=sid,rotation_deg=entity.rotation_deg,confidence=.94,source_refs=src,properties={**common,'fire_component':True}))
        return p
